-- Importacao do cardapio por planilha (F4-0069): the record of applied imports, the key of idempotency.
--   importacoes_cardapio   one row per import applied, keyed by (organizacao_id, id) where id is generated by the client: the same id sent again answers the first result and writes nothing.
--                          conteudo_sha256 fingerprints the file (the same id with another file is told apart from a repeat). The counts are ALL that is kept of the import (no menu data, no file).
--                          Written once, in the same transaction as the menu rows (the application credential has only SELECT and INSERT), so either the rows and this record exist or none does.
-- Tenant data: exact RLS and composite FKs (an import of another organization is refused).
CREATE TABLE importacoes_cardapio (
  id                      uuid        NOT NULL,
  organizacao_id          uuid        NOT NULL REFERENCES organizacoes (id),
  conteudo_sha256         text        NOT NULL CHECK (length(conteudo_sha256) = 64),
  categorias_criadas      integer     NOT NULL CHECK (categorias_criadas >= 0),
  categorias_atualizadas  integer     NOT NULL CHECK (categorias_atualizadas >= 0),
  produtos_criados        integer     NOT NULL CHECK (produtos_criados >= 0),
  produtos_atualizados    integer     NOT NULL CHECK (produtos_atualizados >= 0),
  grupos_criados          integer     NOT NULL CHECK (grupos_criados >= 0),
  grupos_atualizados      integer     NOT NULL CHECK (grupos_atualizados >= 0),
  opcoes_criadas          integer     NOT NULL CHECK (opcoes_criadas >= 0),
  opcoes_atualizadas      integer     NOT NULL CHECK (opcoes_atualizadas >= 0),
  criado_por              uuid        NOT NULL,
  criado_em               timestamptz NOT NULL,
  PRIMARY KEY (organizacao_id, id),
  FOREIGN KEY (organizacao_id, criado_por) REFERENCES contas (organizacao_id, id)
);

ALTER TABLE importacoes_cardapio ENABLE ROW LEVEL SECURITY;
ALTER TABLE importacoes_cardapio FORCE  ROW LEVEL SECURITY;
CREATE POLICY isolamento ON importacoes_cardapio
  USING (organizacao_id = (SELECT app_organizacao_id()))
  WITH CHECK (organizacao_id = (SELECT app_organizacao_id()));

REVOKE UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON importacoes_cardapio FROM flow4tech_app;
REVOKE ALL ON importacoes_cardapio FROM PUBLIC;
